/* From Uiverse.io by PriyanshuGupta28 - Tags: switch, 3d switch, cool switch, creative switch */
.__UIV_SCOPE__ .flipswitch {
  position: relative;
  width: 86px;
}

.__UIV_SCOPE__ .flipswitch input[type=checkbox] {
  display: none;
}

.__UIV_SCOPE__ .flipswitch-label {
  display: block;
  overflow: hidden;
  cursor: pointer;
  border: 1px solid #999999;
  border-radius: 8px;
}

.__UIV_SCOPE__ .flipswitch-inner {
  width: 200%;
  margin-left: -100%;
  transition: margin 0.3s ease-in 0s;
}

.__UIV_SCOPE__ .flipswitch-inner:before, .__UIV_SCOPE__ .flipswitch-inner:after {
  float: left;
  width: 50%;
  height: 24px;
  padding: 0;
  line-height: 24px;
  font-size: 18px;
  color: white;
  font-family: Trebuchet, Arial, sans-serif;
  font-weight: bold;
  box-sizing: border-box;
}

.__UIV_SCOPE__ .flipswitch-inner:before {
  content: "ON";
  padding-left: 12px;
  background-color: #256799;
  color: #FFFFFF;
}

.__UIV_SCOPE__ .flipswitch-inner:after {
  content: "OFF";
  padding-right: 12px;
  background-color: #EBEBEB;
  color: #888888;
  text-align: right;
}

.__UIV_SCOPE__ .flipswitch-switch {
  width: 31px;
  margin: -3.5px;
  background: #FFFFFF;
  border: 1px solid #999999;
  border-radius: 8px;
  position: absolute;
  top: 0;
  bottom: 0;
  right: 59px;
  transition: all 0.3s ease-in 0s;
}

.__UIV_SCOPE__ .flipswitch-cb:checked + .flipswitch-label .flipswitch-inner {
  margin-left: 0;
}

.__UIV_SCOPE__ .flipswitch-cb:checked + .flipswitch-label .flipswitch-switch {
  right: 0;
}
